with open('doc/superhero.md', 'r') as f:
    content = f.read()

import re

# Split into sections
parts = re.split(r'\n{2,}', content)

# Extract ID, Height
height_data = {}
for i, part in enumerate(parts):
    id_match = re.search(r'(?:under|reference|identifier)[^0-9]*(\d+)\b', part)
    if id_match:
        hero_id = id_match.group(1)
    else:
        continue
    height_match = re.search(r'(\d+\.?\d*)\s*centimeters', part)
    if height_match:
        height = float(height_match.group(1))
        height_data[hero_id] = height

# Extract ID, Publisher
publisher_data = {}
for i, part in enumerate(parts):
    id_match = re.search(r'(?:under|reference|identifier)[^0-9]*(\d+)\b', part)
    if id_match:
        hero_id = id_match.group(1)
    else:
        continue
    pub_match = re.search(r'publisher[^0-9]*(\d+)', part)
    if pub_match:
        pub_code = pub_match.group(1)
        publisher_data[hero_id] = pub_code

# Join by ID
hero_data = {}
for hero_id in height_data:
    if hero_id in publisher_data:
        hero_data[hero_id] = {
            'height': height_data[hero_id],
            'publisher': publisher_data[hero_id]
        }

print(f"Total heroes with both height and publisher: {len(hero_data)}")

# Filter for height between 150-180
filtered_heroes = {hid: data for hid, data in hero_data.items() 
                  if 150 <= data['height'] <= 180}

print(f"Heroes with height 150-180: {len(filtered_heroes)}")

# Count Marvel (publisher 13)
marvel_count = sum(1 for data in filtered_heroes.values() if data['publisher'] == '13')

print(f"Marvel (publisher 13) count: {marvel_count}")

# Calculate percentage
percentage = (marvel_count / len(filtered_heroes)) * 100 if filtered_heroes else 0
print(f"Percentage: {percentage:.2f}%")

# Show details
print("\nHeroes in range with publisher info:")
for hid, data in filtered_heroes.items():
    print(f"  ID {hid}: height={data['height']}, publisher={data['publisher']}")

